<?phpadd_action('admin_menu', 'tns_register_menu');function tns_register_menu() {    add_menu_page(        'تنظیمات قالب',        'تنظیمات قالب',        'manage_options',        'setting_shop',        'setting_shop_layout',        'dashicons-sos',        25    );    add_submenu_page(        'setting_shop',        'تنظیمات عمومی',        'تنظیمات عمومی',        'manage_options',        'setting_shop_tab_one',        'setting_shop_layout'    );    add_submenu_page(        'setting_shop',        'مدیریت سلایدر',        'مدیریت سلایدر',        'manage_options',        'setting_shop_tab_three',        'setting_shop_layout'    );    add_submenu_page(        'setting_shop',        'تماس با ما',        'تماس با ما',        'manage_options',        'setting_shop_tab_four',        'setting_shop_layout'    );    add_submenu_page(        'setting_shop',        'مدیریت شبکه‌های اجتماعی',        'مدیریت شبکه‌های اجتماعی',        'manage_options',        'setting_shop_tab_five',        'setting_shop_layout'    );    add_submenu_page(        'setting_shop',        'سوالات متداول (FAQ)',        'سوالات متداول (FAQ)',        'manage_options',        'setting_shop_tab_six',        'setting_shop_layout'    );    // تنظیمات SMS - فقط در صورت فعال بودن    $general_settings = get_option('_shw_settings_set_general', []);    $sms_setting = isset($general_settings['register_from_sms_enable']) ? $general_settings['register_from_sms_enable'] : 'no';    if ($sms_setting === 'yes') {        add_submenu_page(            'setting_shop',            'تنظیمات پیامک (SMS)',            'تنظیمات پیامک',            'manage_options',            'setting_shop_tab_seven',            'setting_shop_layout'        );    }    add_submenu_page(            'edit.php',            'لیست علاقه مندی ها',            'لیست علاقه مندی ها',            'manage_options',            'wishlist_setting',            'shw_wishlist_setting_list_layout',            ''    );}function setting_shop_layout() {    if (!current_user_can('manage_options')) {        wp_die('دسترسی غیرمجاز!');    }    $page = isset($_GET['page']) ? $_GET['page'] : 'setting_shop_tab_one';    $tab = str_replace('setting_shop_', '', $page);    // دریافت دوباره تنظیمات برای تب SMS    $general_settings = get_option('_shw_settings_set_general', []);    $sms_setting = isset($general_settings['register_from_sms_enable']) ? $general_settings['register_from_sms_enable'] : 'no';    ?>    <div class="wrap">        <h1 class="nav-tab-wrapper">            <a href="?page=setting_shop_tab_one" class="nav-tab <?php echo $tab === 'tab_one' ? 'nav-tab-active' : ''; ?>">                تنظیمات عمومی            </a>            <a href="?page=setting_shop_tab_three" class="nav-tab <?php echo $tab === 'tab_three' ? 'nav-tab-active' : ''; ?>">                مدیریت اسلایدر            </a>            <a href="?page=setting_shop_tab_four" class="nav-tab <?php echo $tab === 'tab_four' ? 'nav-tab-active' : ''; ?>">                تماس با ما            </a>            <a href="?page=setting_shop_tab_five" class="nav-tab <?php echo $tab === 'tab_five' ? 'nav-tab-active' : ''; ?>">                شبکه‌های اجتماعی            </a>            <a href="?page=setting_shop_tab_six" class="nav-tab <?php echo $tab === 'tab_six' ? 'nav-tab-active' : ''; ?>">                سوالات متداول (FAQ)            </a>            <?php if ($sms_setting === 'yes') { ?>                <a href="?page=setting_shop_tab_seven" class="nav-tab <?php echo $tab === 'tab_seven' ? 'nav-tab-active' : ''; ?>">                    تنظیمات پیامک                </a>            <?php } ?>        </h1>        <div class="tab-content" style="margin-top: 20px;">            <?php            switch ($tab) {                case 'tab_one':                    tnm_general_setting_html_layout();                    break;                case 'tab_three':                    tnm_banner_setting_html_layout();                    break;                case 'tab_four':                    tnm_contact_us_setting_layout();                    break;                case 'tab_five':                    tnm_social_media_html_layout();                    break;                case 'tab_six':                    tnm_faq_html_layout();                    break;                case 'tab_seven':                    tnm_setting_sms_layout();                    break;                default:                    shw_info_setup_theme();            }            ?>        </div>    </div>    <?php}// ========== توابع فراخوانی فایل‌ها ==========function tnm_general_setting_html_layout() {    require_once 'view/general-setting-html-layout.php';}function tnm_banner_setting_html_layout() {    require_once 'view/banner-setting-html-layout.php';}function tnm_contact_us_setting_layout() {    require_once 'view/contact-us-setting-layout.php';}function tnm_social_media_html_layout() {    require_once 'view/social-media-html-layout.php';}function tnm_faq_html_layout() {    require_once 'view/faq-setting-html-layout.php';}function tnm_setting_sms_layout() {    require_once 'view/sms-setting-layout.php';}function shw_info_setup_theme(): void{    require_once 'view/info-setup-theme.php';}function shw_wishlist_setting_list_layout(): void{    if (!current_user_can('manage_options')) {        wp_die('دسترسی غیرمجاز!');    }    $tab = isset($_GET['tab']) ? sanitize_key($_GET['tab']) : 'all';    ?>    <div class="wrap">        <h1>لیست علاقه مندی ها</h1>        <nav class="nav-tab-wrapper">            <a href="<?php echo admin_url('edit.php?page=wishlist_setting&tab=all'); ?>"               class="nav-tab <?php echo ($tab === 'all') ? 'nav-tab-active' : ''; ?>">                همه علاقه مندی ها            </a>            <a href="<?php echo admin_url('edit.php?page=wishlist_setting&tab=popular'); ?>"               class="nav-tab <?php echo ($tab === 'popular') ? 'nav-tab-active' : ''; ?>">                پست های محبوب            </a>        </nav>        <div class="tab-content" style="margin-top:20px;">            <?php            switch ($tab) {                case 'all':                    echo '<div class="notice notice-info"><p>لیست تمام علاقه مندی ها</p></div>';                    // اینجا جدول علاقه مندی ها                    shw_wishlist_all_layout();                    break;                case 'popular':                    echo '<div class="notice notice-success"><p>پست های محبوب</p></div>';                    shw_wishlist_popular_layout();                    break;                default:                    echo '<div class="notice notice-error"><p>تب نامعتبر است.</p></div>';                    break;            }            ?>        </div>    </div>    <?php}function shw_wishlist_all_layout(): void{    require_once 'view/wishlist/wishlist-all-layout.php';}function shw_wishlist_popular_layout(): void{    require_once 'view/wishlist/wishlist-popular-layout.php';}?>